CREATE TABLE organizations(id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE sites(id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), code text NOT NULL, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Bangkok', demo boolean NOT NULL DEFAULT false, UNIQUE(organization_id,code));
CREATE TABLE users(id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), email text UNIQUE NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, demo boolean NOT NULL DEFAULT false);
CREATE TABLE grants(user_id text REFERENCES users(id), site_id text REFERENCES sites(id), role text NOT NULL CHECK(role IN('EO','DO','ES','MG','SA','AV')), PRIMARY KEY(user_id,site_id,role));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE master_versions(id text PRIMARY KEY, site_id text NOT NULL REFERENCES sites(id), kind text NOT NULL, code text NOT NULL, name text NOT NULL, version int NOT NULL CHECK(version>0), status text NOT NULL CHECK(status IN('DRAFT','SUBMITTED','ACTIVE','SUPERSEDED','INACTIVE')), effective_from date NOT NULL, effective_to date, config jsonb NOT NULL DEFAULT '{}', created_by text NOT NULL REFERENCES users(id), approved_by text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK(effective_to IS NULL OR effective_to>=effective_from), CHECK(approved_by IS NULL OR approved_by<>created_by), UNIQUE(site_id,kind,code,version));
CREATE UNIQUE INDEX master_current ON master_versions(site_id,kind,code) WHERE status='ACTIVE';
CREATE TABLE record_families(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),business_key text NOT NULL,created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,business_key),UNIQUE(id,site_id));
CREATE TABLE record_versions(id text PRIMARY KEY,family_id text NOT NULL,site_id text NOT NULL,version int NOT NULL CHECK(version>0),lock_version int NOT NULL DEFAULT 1,status text NOT NULL CHECK(status IN('DRAFT','SUBMITTED','APPROVED','REJECTED','SUPERSEDED','VOIDED')),category text NOT NULL CHECK(category IN('WATER','WASTEWATER','ENERGY','WASTE','PRODUCTION')),asset_code text NOT NULL,parameter_code text NOT NULL,event_date date NOT NULL,value numeric(24,8),unit text NOT NULL,kind text NOT NULL,raw_value text,qualifier text,source text NOT NULL,source_ref text NOT NULL DEFAULT '',note text NOT NULL DEFAULT '',payload jsonb NOT NULL DEFAULT '{}',config_snapshot jsonb NOT NULL DEFAULT '{}',created_by text NOT NULL REFERENCES users(id),submitted_by text REFERENCES users(id),approved_by text REFERENCES users(id),reason text NOT NULL DEFAULT '',demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,FOREIGN KEY(family_id,site_id) REFERENCES record_families(id,site_id),UNIQUE(family_id,version),UNIQUE(id,site_id),CHECK(value IS NULL OR value>=0),CHECK(approved_by IS NULL OR (approved_by<>created_by AND approved_by<>submitted_by)));
CREATE UNIQUE INDEX record_current ON record_versions(family_id) WHERE status='APPROVED';
CREATE UNIQUE INDEX record_pending ON record_versions(family_id) WHERE status IN('DRAFT','SUBMITTED');
CREATE INDEX record_analytics ON record_versions(site_id,event_date,category,status);
CREATE TABLE import_batches(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),created_by text NOT NULL REFERENCES users(id),checksum text NOT NULL,filename text NOT NULL,mapping jsonb NOT NULL,rows jsonb NOT NULL,status text NOT NULL DEFAULT 'PREVIEW',result jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,checksum));
CREATE TABLE alerts(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),rule_id text NOT NULL REFERENCES master_versions(id),record_id text NOT NULL, status text NOT NULL DEFAULT 'NEW' CHECK(status IN('NEW','ACKNOWLEDGED','LINKED','DISMISSED','RESOLVED')),severity text NOT NULL,summary text NOT NULL,snapshot jsonb NOT NULL,source_changed boolean NOT NULL DEFAULT false,episode_key text NOT NULL,episode_open boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(record_id,site_id) REFERENCES record_versions(id,site_id),UNIQUE(id,site_id));
CREATE UNIQUE INDEX alert_episode ON alerts(episode_key) WHERE episode_open=true;
CREATE TABLE issues(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),number text UNIQUE NOT NULL,title text NOT NULL,description text NOT NULL,category text NOT NULL,severity text NOT NULL CHECK(severity IN('LOW','MEDIUM','HIGH','CRITICAL')),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','ASSIGNED','INVESTIGATING','ACTION_IN_PROGRESS','WAITING_VERIFICATION','VERIFIED','CLOSED','REOPENED','CANCELLED')),created_by text NOT NULL REFERENCES users(id),owner_id text REFERENCES users(id),verifier_id text REFERENCES users(id),original_due date,due_date date,detected_date date NOT NULL,source_record_id text,alert_id text,workflow_snapshot jsonb NOT NULL DEFAULT '{}',investigation text NOT NULL DEFAULT '',root_cause text NOT NULL DEFAULT '',completion text NOT NULL DEFAULT '',closure text NOT NULL DEFAULT '',closed_at timestamptz,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(source_record_id,site_id) REFERENCES record_versions(id,site_id),FOREIGN KEY(alert_id,site_id) REFERENCES alerts(id,site_id),CHECK(owner_id IS NULL OR verifier_id<>owner_id),UNIQUE(id,site_id));
CREATE INDEX issue_queue ON issues(site_id,status,due_date);
CREATE TABLE tasks(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),issue_id text NOT NULL,description text NOT NULL,owner_id text NOT NULL REFERENCES users(id),due_date date NOT NULL,required boolean NOT NULL DEFAULT true,status text NOT NULL DEFAULT 'TODO' CHECK(status IN('TODO','IN_PROGRESS','DONE')),result text NOT NULL DEFAULT '',completed_by text REFERENCES users(id),version int NOT NULL DEFAULT 1,FOREIGN KEY(issue_id,site_id) REFERENCES issues(id,site_id));
CREATE TABLE evidence(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),issue_id text,record_id text,document_id text NOT NULL,version int NOT NULL DEFAULT 1,filename text NOT NULL,mime text NOT NULL,size int NOT NULL,sha256 text NOT NULL,object_key text NOT NULL UNIQUE,provider text NOT NULL,scan_status text NOT NULL,available boolean NOT NULL DEFAULT true,uploaded_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(issue_id,site_id) REFERENCES issues(id,site_id),FOREIGN KEY(record_id,site_id) REFERENCES record_versions(id,site_id),CHECK(issue_id IS NOT NULL OR record_id IS NOT NULL),UNIQUE(document_id,version));
CREATE TABLE verifications(id text PRIMARY KEY,issue_id text NOT NULL REFERENCES issues(id),cycle int NOT NULL,status text NOT NULL CHECK(status IN('WAITING','REJECTED','VERIFIED','INVALIDATED')),requested_by text NOT NULL REFERENCES users(id),decided_by text REFERENCES users(id),checklist jsonb NOT NULL, fingerprint text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(issue_id,cycle));
CREATE TABLE reports(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),title text NOT NULL,period_start date NOT NULL,period_end date NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','IN_REVIEW','APPROVED','PUBLISHED','REJECTED')),created_by text NOT NULL REFERENCES users(id),approved_by text REFERENCES users(id),snapshot jsonb NOT NULL,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CHECK(period_end>=period_start),CHECK(approved_by IS NULL OR approved_by<>created_by));
CREATE TABLE events(id text PRIMARY KEY,site_id text REFERENCES sites(id),actor_id text REFERENCES users(id),entity_type text NOT NULL,entity_id text NOT NULL,action text NOT NULL,reason text NOT NULL DEFAULT '',before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX event_timeline ON events(site_id,entity_id,created_at);
CREATE TABLE notifications(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),user_id text NOT NULL REFERENCES users(id),event_id text NOT NULL REFERENCES events(id),title text NOT NULL,href text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_id));
CREATE TABLE idempotency(user_id text NOT NULL REFERENCES users(id),request_key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,request_key));
CREATE FUNCTION forbid_event_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit events are immutable'; END $$;
CREATE TRIGGER events_immutable BEFORE UPDATE OR DELETE ON events FOR EACH ROW EXECUTE FUNCTION forbid_event_change();
CREATE FUNCTION protect_approved_fact() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status IN ('APPROVED','SUPERSEDED','VOIDED') AND (to_jsonb(NEW)-'status'-'lock_version') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'lock_version') THEN RAISE EXCEPTION 'Approved facts are immutable; create a revision'; END IF; RETURN NEW; END $$;
CREATE TRIGGER approved_fact_immutable BEFORE UPDATE ON record_versions FOR EACH ROW EXECUTE FUNCTION protect_approved_fact();
